  // ===== Патенты =====
  'pat.eyebrow': { ru: '04 · Патенты и товарные знаки', en: '04 · Patents and trademarks', zh: '04 · 专利与商标' , kk: '04 · Патенттер мен тауар белгілері', hy: '04 · Պատենտներ և ապրանքանիշներ', ka: '04 · პატენტები და სავაჭრო ნიშნები'},
  'pat.h2Pre': { ru: 'Интеллектуальная собственность', en: 'Intellectual property of', zh: 'СРОСС® 的知识产权' , kk: 'Интеллектуалды меншік', hy: 'Մտավոր սեփականություն', ka: 'ინტელექტუალური საკუთრება'},
  'pat.lead': { ru: 'Авторский коллектив системы под руководством Акбиева Рустама Тогановича — автор 71 патента на изобретения и полезные модели (1973—2018), из которых 8 ключевых патентов напрямую посвящены сейсмобезопасности зданий и сооружений.', en: 'The system’s author team led by Rustam Toganovich Akbiev — holder of 71 patents for inventions and utility models (1973–2018), 8 key of which are directly devoted to the seismic safety of buildings and structures.', zh: '由鲁斯塔姆·托加诺维奇·阿克比耶夫领导的系统作者团队——拥有71项发明和实用新型专利（1973–2018年），其中8项关键专利直接涉及建筑与结构的抗震安全。' , kk: 'Жүйенің авторлық ұжымын Рұстам Тоғанұлы Әкбиев басқарды — ол 1973-2018 жылдарында 71 өнертабыстық және пайдалы модель патенттерінің авторы, оның ішінде 8 негізгі патент ғимараттар мен құрылыстардың сейсмикалық қауіпсіздігіне тікелей арналған.', hy: 'Ռուստամ Տոգանովիչ Ակբիևի ղեկավարած համակարգի հեղինակային թիմը 71 գյուտի և օգտակար մոդելի արտոնագրերի (1973—2018) հեղինակ է, որոնցից 8-ը նվիրված են շենքերի և կառույցների սեյսմիկ անվտանգությանը։', ka: 'რუსტამ ტოგანოვიჩ აქბიევის ხელმძღვანელობით სისტემის ავტორთა ჯგუფი არის 71 გამოგონებისა და სასარგებლო მოდელის პატენტის (1973—2018) ავტორი, რომელთაგან 8 ძირითადი პატენტი პირდაპირ ეძღვნება შენობებისა და ნაგებობების მიწისძვრისდაცადი უსაფრთხოებას։'},
  'pat.st1': { ru: 'всего патентов', en: 'total patents', zh: '项专利总数' , kk: 'барлық патенттер', hy: 'ընդհանուր արտոնագրեր', ka: 'ჯამში პატენტები'},
